#include <bits/stdc++.h>
using namespace std;
typedef long long ll;

int main() {
    int rows, cols, r;
    scanf("%d %d %d", &rows, &cols, &r);
    vector<vector<ll>> pref(rows, vector<ll>(cols + 1, 0));  // row prefix sums
    for (int i = 0; i < rows; i++)
        for (int j = 0; j < cols; j++) { ll x; scanf("%lld", &x); pref[i][j + 1] = pref[i][j] + x; }
    bool found = false;
    ll best = 0;
    for (int cr = r - 1; cr <= rows - r; cr++)
        for (int cc = r - 1; cc <= cols - r; cc++) {
            ll total = 0;
            // Row cr+dr contributes columns with |dc| <= r-1-|dr|.
            for (int dr = -(r - 1); dr < r; dr++) {
                int rr = cr + dr;
                if (rr < 0 || rr >= rows) continue;
                int span = r - 1 - abs(dr), lo = max(0, cc - span), hi = min(cols - 1, cc + span);
                total += pref[rr][hi + 1] - pref[rr][lo];
            }
            if (!found || total > best) { best = total; found = true; }
        }
    printf("%lld\n", found ? best : 0LL);
}

import java.io.*;

public class Main {
    static byte[] buf;
    static int bp;

    static long nextLong() {
        while (buf[bp] <= ' ') bp++;
        boolean neg = buf[bp] == '-';
        if (neg) bp++;
        long r = 0;
        while (bp < buf.length && buf[bp] > ' ') r = r * 10 + (buf[bp++] - '0');
        return neg ? -r : r;
    }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        int rows = (int) nextLong(), cols = (int) nextLong(), r = (int) nextLong();
        long[][] pref = new long[rows][cols + 1];  // row prefix sums
        for (int i = 0; i < rows; i++)
            for (int j = 0; j < cols; j++) pref[i][j + 1] = pref[i][j] + nextLong();
        boolean found = false;
        long best = 0;
        for (int cr = r - 1; cr <= rows - r; cr++)
            for (int cc = r - 1; cc <= cols - r; cc++) {
                long total = 0;
                // Row cr+dr contributes columns with |dc| <= r-1-|dr|.
                for (int dr = -(r - 1); dr < r; dr++) {
                    int rr = cr + dr;
                    if (rr < 0 || rr >= rows) continue;
                    int span = r - 1 - Math.abs(dr), lo = Math.max(0, cc - span), hi = Math.min(cols - 1, cc + span);
                    total += pref[rr][hi + 1] - pref[rr][lo];
                }
                if (!found || total > best) { best = total; found = true; }
            }
        System.out.println(found ? best : 0);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
)

func main() {
	sc := bufio.NewScanner(os.Stdin)
	sc.Buffer(make([]byte, 1<<20), 1<<26)
	sc.Split(bufio.ScanWords)
	next := func() int64 { sc.Scan(); v, _ := strconv.ParseInt(sc.Text(), 10, 64); return v }
	rows, cols, r := int(next()), int(next()), int(next())
	pref := make([][]int64, rows) // row prefix sums
	for i := range pref {
		pref[i] = make([]int64, cols+1)
		for j := 0; j < cols; j++ {
			pref[i][j+1] = pref[i][j] + next()
		}
	}
	found, best := false, int64(0)
	for cr := r - 1; cr <= rows-r; cr++ {
		for cc := r - 1; cc <= cols-r; cc++ {
			var total int64
			// Row cr+dr contributes columns with |dc| <= r-1-|dr|.
			for dr := -(r - 1); dr < r; dr++ {
				rr := cr + dr
				if rr < 0 || rr >= rows {
					continue
				}
				span := r - 1 - max(dr, -dr)
				lo, hi := max(0, cc-span), min(cols-1, cc+span)
				total += pref[rr][hi+1] - pref[rr][lo]
			}
			if !found || total > best {
				best, found = total, true
			}
		}
	}
	fmt.Println(best)
}
